{
  "analysis": "The input files and SOP IA-07 have been read. Next we need to inspect plate_layout.tsv, annotations, flatfield files, and examine the wells to see if any wells are out of focus (image QC). We also need to understand the cell counting criteria and flatfield correction.",
  "plan": "Inspect plate_layout.tsv, annotations directory, check image shapes/stats, and explore focus/QC issues.",
  "commands": [
    {
      "keystrokes": "head -n 20 /task/input/plate_layout.tsv\n",
      "duration": 0.2
    },
    {
      "keystrokes": "ls -la /task/input/annotations\n",
      "duration": 0.2
    },
    {
      "keystrokes": "python3 -c \"
import os, glob
import pandas as pd
