      "keystrokes": "python3 -c \"\nimport tifffile, pandas as pd, numpy as np\npl = pd.read_csv('/task/input/plate_layout.tsv', sep='\\t')\nvehicles = pl[pl['role'] == 'vehicle']\nprint(vehicles)\nfor w in vehicles['well']:\n    im1 = tifffile.imread(f'/task/input/images/{w}_ch1.tif')\n    im2 = tifffile.imread(f'/task/input/images/{w}_ch2.tif')\n    print(f'{w}: ch1 min={im1.min()} max={im1.max()} mean={im1.mean():.1f} std={im1.std():.1f} | ch2 min={im2.min()} max={im2.max()} mean={im2.mean():.1f}')\n\" \n",
